   // outer petals\n        for (var i = 0; i < 6; i++) {\n          var a = i * Math.PI / 3 + 0.3;\n          ctx.beginPath(); ctx.ellipse(Math.cos(a) * r * 0.42, Math.sin(a) * r * 0.42, r * 0.58, r * 0.42, a, 0, Math.PI * 2); ctx.fill();\n        }\n        ctx.fillStyle = c1; ctx.beginPath(); ctx.arc(0, 0, r * 0.62, 0, Math.PI * 2); ctx.fill();\n        // swirl\n        ctx.strokeStyle = c2; ctx.lineCap = 'round';\n        for (var k = 0; k < 4; k++) {\n          ctx.globalAlpha = 0.55; ctx.lineWidth = Math.max(1, r * (0.07 - k * 0.012));\n          ctx.beginPath(); ctx.arc(r * 0.04 * k, -r * 0.03 * k, r * (0.5 - k * 0.11), 0.3 + k * 1.3, 0.3 + k * 1.3 + Math.PI * 1.2); ctx.stroke();\n        }\n        ctx.globalAlpha = 0.5; ctx.fillStyle = '#ffffff';\n        ctx.beginPath(); ctx.ellipse(-r * 0.32, -r * 0.38, r * 0.16, r * 0.07, -0.6, 0, Math.PI * 2); ctx.fill();\n        ctx.restore();\n      }\n      function drawRoseCluster(ctx, x, y, r, rot) {\n        ctx.save(); ctx.translate(x, y); ctx.rotate(rot);\n        drawLeaf(ctx, r * 1.25, r * 0.15, r * 0.9, 0.25); drawLeaf(ctx, r * 0.35, r * 1.15, r * 0.85, 1.35);\n        drawLeaf(ctx, r * 1.6, -r * 0.45, r * 0.7, -0.3); drawLeaf(ctx, -r * 0.5, r * 1.3, r * 0.6, 1.9);\n        drawRose(ctx, 0, 0, r, 0.2);\n        drawRose(ctx, r * 1.05, r * 0.75, r * 0.62, -0.5);\n        drawRose(ctx, -r * 0.25, r * 0.95, r * 0.45, 0.9);\n        ctx.fillStyle = apal('rose', '#f2a7b8'); ctx.globalAlpha = 0.6;\n        [[1.9, 0.2, 0.08], [1.5, 1.2, 0.06], [0.6, 1.8, 0.07], [2.1, -0.6, 0.05]].forEach(function (d) { ctx.beginPath(); ctx.arc(d[0] * r, d[1] * r, d[2] * r, 0, Math.PI * 2); ctx.fill(); });\n        ctx.restore();\n      }\n      function drawPampas(ctx, x, by, H, lean) {\n        var col = mixHex(apal('pampas', '#d9c3a3'), '#8a6a45', 0.25);\n        ctx.save(); ctx.lineCap = 'round';\n        var dir = lean < -0.05 ? 1 : -1;     // plumes fan toward the middle\n        [[-0.12, 1, 0], [0.1, 0.82, 0.25], [0.28, 0.66, 0.5]].forEach(function (p, j) {\n          var ang = lean + p[0] * dir, h = H * p[1], tipX = x + Math.sin(ang) * h, tipY = by - Math.cos(ang) * h;\n          ctx.strokeStyle = mixHex(col, '#8a6a45', 0.45); ctx.lineWidth = Math.max(1.5, H * 0.008);\n          ctx.beginPath(); ctx.moveTo(x, by); ctx.quadraticCurveTo(x + Math.sin(ang) * h * 0.5 + lean * h * 0.1, by - Math.cos(ang) * h * 0.55, tipX, tipY); ctx.stroke();\n          var rand = seededRand(77 + j);\n          for (var i = 0; i < 60; i++) {\n            var t = 0.45 + rand() * 0.55, px = x + (tipX - x) * t, py = by + (tipY - by) * t;\n            var fl = H * (0.05 + 0.08 * Math.sin(Math.PI * (t - 0.45) / 0.55)), a = ang + (rand() < 0.5 ? -1 : 1) * (0.5 + rand() * 0.6);\n            ctx.strokeStyle = mixHex(col, '#ffffff', rand() * 0.4); ctx.globalAlpha = 0.55 + rand() * 0.35; ctx.lineWidth = Math.max(1, H * (0.004 + rand() * 0.006));\n            ctx.beginPath(); ctx.moveTo(px, py); ctx.quadraticCurveTo(px + Math.sin(a) * fl * 0.6, py - Math.cos(a) * fl * 0.4, px + Math.sin(a) * fl, py - Math.cos(a) * fl); ctx.stroke();\n          }\n          ctx.globalAlpha = 1;\n        });\n        ctx.restore();\n      }\n\n      // ---- Landscape 4R layouts (event name in its own panel) ----\n      function landscapeCells(key, W, H) {\n        var m = H * 0.035, g = H * 0.025, iw = W - 2 * m, ih = H - 2 * m;\n        if (key === 'land2' || key === 'land2t') {\n          // Two big photos side by side and the event name in a wide band under them (land2) or over them (land2t).\n          var nameH = ih * 0.2, picH = ih - g - nameH, pw2 = (iw - g) / 2, py = key === 'land2' ? m : m + nameH + g;\n          return {\n            title: { x: m, y: key === 'land2' ? m + picH + g : m, w: iw, h: nameH },\n            shots: [0, 1].map(function (i) { return { x: m + i * (pw2 + g), y: py, w: pw2, h: picH }; })\n          };\n        }\n        if (key === 'land4') {\n          var topH = (ih - g) * 0.55, botH = ih - g - topH, bw = (iw - 2 * g) / 3, lw = (iw - g) * 0.55;\n          return {\n            title: { x: m + lw + g, y: m, w: iw - lw - g, h: topH },\n            shots: [{ x: m, y: m, w: lw, h: topH }].concat([0, 1, 2].map(function (i) { return { x: m + i * (bw + g), y: m + topH + g, w: bw, h: botH }; }))\n          };\n        }\n        var cw = (iw - g) / 2, chh = (ih - g) / 2;\n        return {\n          title: { x: m, y: m, w: cw, h: chh },\n          shots: [{ x: m + cw + g, y: m, w: cw, h: chh }, { x: m, y: m + chh + g, w: cw, h: chh }, { x: m + cw + g, y: m + chh + g, w: cw, h: chh }]\n        };\n      }\n      function composeLandscape(layoutKey, targetCanvas, shots) {\n        var sc = offlineOutputScale(targetCanvas, 'landscape');\n        var W = Math.round(SHEET_H * sc), H = Math.round(SHEET_W * sc);\n        targetCanvas.width = W; targetCanvas.height = H;\n        var ctx = targetCanvas.getContext('2d');\n        ctx.imageSmoothingEnabled = true; ctx.imageSmoothingQuality = 'high';\n        currentFrameColor = frameColorFor();\n        drawBackdrop(ctx, W, H);\n        var L = landscapeCells(layoutKey, W, H);\n        L.shots.forEach(function (c, i) {\n          ctx.save();\n          ctx.shadowColor = 'rgba(40,30,20,0.25)'; ctx.shadowBlur = Math.round(16 * sc); ctx.shadowOffsetY = Math.round(5 * sc);\n          ctx.fillStyle = currentFrameColor; ctx.fillRect(c.x, c.y, c.w, c.h);\n          ctx.restore();\n          var pad = Math.max(6, Math.min(c.w, c.h) * 0.03);\n          if (shots[i]) drawImageCover(ctx, shots[i], c.x + pad, c.y + pad, c.w - 2 * pad, c.h - 2 * pad);\n        });\n        var t = L.title;\n        drawLabelBand(ctx, t.w, t.y, t.h, labelInput.value, t.x);\n        drawThemeArt(ctx, W, H, t);\n        if (typeof drawDecorLayer === 'function') drawDecorLayer(ctx, W, H);\n        return targetCanvas;\n      }\n\n      // ---- Receipt layouts ----\n      // 576 px wide = 80 mm thermal paper at 203 dpi (the printer's own dots).\n      // On screen, QR copies, and photo paper, black & white receipts render as clean, smooth\n      // black & white (2x crisp on output targets, no grainy dithering). When building for a thermal\n      // roll (receiptPrintGrey), photo boxes get backlit shadow recovery, dot-gain tone mapping, and\n      // halo-free facial clarity while text & barcode stay pure solid black; the thermal printer step\n      // then converts the page to dots once at the printer's exact dot width.\n      const RECEIPT_W = 576, RECEIPT_DPI = 203;\n      const receiptTimes = {};\n      function receiptTime(n) {\n        if (!receiptTimes[n]) receiptTimes[n] = new Date();\n        return receiptTimes[n];\n      }\n      let receiptPrintGrey = false;\n      let receiptPrint58 = false;\n      function receiptBoxBlur(src, w, h, r) {\n        const n = w * h, tmp = new Float32Array(n), out = new Float32Array(n);\n        const inv = 1 / (2 * r + 1);\n        for (let y = 0; y < h; y++) {\n          const row = y * w;\n          let acc = src[row] * (r + 1);\n          for (let x = 1; x <= r; x++) acc += src[row + (x < w ? x : w - 1)];\n          for (let x = 0; x < w; x++) {\n            tmp[row + x] = acc * inv;\n            const x0 = x - r, x1 = x + r + 1;\n            acc += src[row + (x1 < w ? x1 : w - 1)] - src[row + (x0 > 0 ? x0 : 0)];\n          }\n        }\n        for (let x = 0; x < w; x++) {\n          let acc = tmp[x] * (r + 1);\n          for (let y = 1; y <= r; y++) acc += tmp[(y < h ? y : h - 1) * w + x];\n          for (let y = 0; y < h; y++) {\n            out[y * w + x] = acc * inv;\n            const y0 = y - r, y1 = y + r + 1;\n            acc += tmp[(y1 < h ? y1 : h - 1) * w + x] - tmp[(y0 > 0 ? y0 : 0) * w + x];\n          }\n        }\n        return out;\n      }\n      function ditherRegion(ctx, x, y, w, h) {\n        x = Math.round(x); y = Math.round(y); w = Math.round(w); h = Math.round(h);\n        if (w <= 0 || h <= 0) return;\n        const im = ctx.getImageData(x, y, w, h), d = im.data;\n        if (!receiptPrintGrey) {\n          // Screen preview, QR digital copy, and photo paper: clean, plain smooth black & white (no grainy dithering).\n          for (let i = 0; i < d.length; i += 4) {\n            const v = Math.round(0.299 * d[i] + 0.587 * d[i + 1] + 0.114 * d[i + 2]);\n            d[i] = d[i + 1] = d[i + 2] = v;\n            d[i + 3] = 255;\n          }\n          ctx.putImageData(im, x, y);\n          return;\n        }\n        // Thermal roll print: smooth grayscale tuned for 203 dpi thermal paper (applied to photo boxes only).\n        const n = w * h, g = new Float32Array(n);\n        for (let i = 0, j = 0; j < n; i += 4, j++) g[j] = 0.299 * d[i] + 0.587 * d[i + 1] + 0.114 * d[i + 2];\n        const adjB = (typeof colorAdj !== 'undefined' && colorAdj && Number(colorAdj.brightness)) || 0;\n        const tq = (typeof printPrefs !== 'undefined' && printPrefs && printPrefs.thermalQuality) || 'best';\n        // 1. Fast edge-preserving 3x3 bilateral denoise: smooths ISO noise in flat skies & skin without softening eyes.\n        const clean = new Float32Array(n);\n        clean.set(g);\n        const invT2 = 1 / 144;\n        for (let yy = 1; yy < h - 1; yy++) {\n          const rm = (yy - 1) * w, r0 = yy * w, rp = (yy + 1) * w;\n          for (let xx = 1; xx < w - 1; xx++) {\n            const c0 = g[r0 + xx];\n            let s = c0, sw = 1, v, df, wt;\n            v = g[rm + xx - 1]; df = v - c0; wt = 1 / (1 + df * df * invT2); s += v * wt; sw += wt;\n            v = g[rm + xx];     df = v - c0; wt = 1 / (1 + df * df * invT2); s += v * wt; sw += wt;\n            v = g[rm + xx + 1]; df = v - c0; wt = 1 / (1 + df * df * invT2); s += v * wt; sw += wt;\n            v = g[r0 + xx - 1]; df = v - c0; wt = 1 / (1 + df * df * invT2); s += v * wt; sw += wt;\n            v = g[r0 + xx + 1]; df = v - c0; wt = 1 / (1 + df * df * invT2); s += v * wt; sw += wt;\n            v = g[rp + xx - 1]; df = v - c0; wt = 1 / (1 + df * df * invT2); s += v * wt; sw += wt;\n            v = g[rp + xx];     df = v - c0; wt = 1 / (1 + df * df * invT2); s += v * wt; sw += wt;\n            v = g[rp + xx + 1]; df = v - c0; wt = 1 / (1 + df * df * invT2); s += v * wt; sw += wt;\n            clean[r0 + xx] = s / sw;\n          }\n        }\n        // 2. Large-scale local illumination on 4x downsampled grid for backlit shadow recovery.\n        const ds = 4, sw = Math.max(4, Math.ceil(w / ds)), sh = Math.max(4, Math.ceil(h / ds));\n        const small = new Float32Array(sw * sh);\n        for (let sy = 0; sy < sh; sy++) {\n          const y0 = sy * ds, y1 = Math.min(h, y0 + ds);\n          for (let sx = 0; sx < sw; sx++) {\n            const x0 = sx * ds, x1 = Math.min(w, x0 + ds);\n            let sum = 0, cnt = 0;\n            for (let yy = y0; yy < y1; yy++) {\n              const rr = yy * w;\n              for (let xx = x0; xx < x1; xx++) { sum += clean[rr + xx]; cnt++; }\n            }\n            small[sy * sw + sx] = sum / cnt;\n          }\n        }\n        const sr = Math.max(3, Math.min(12, Math.round(Math.min(sw, sh) * 0.1)));\n        const locS = receiptBoxBlur(receiptBoxBlur(small, sw, sh, sr), sw, sh, sr);\n        // 3. Local shadow recovery + highlight-safe thermal dot-gain curve + printer Lightness (applied once).\n        const gBase = receiptPrint58 ? 0.75 : 0.80;\n        const B = 32, lut = new Float32Array(B * 256);\n        for (let b = 0; b < B; b++) {\n          const dark = b / (B - 1), effG = gBase / (1 + dark * 0.65), base = b * 256;\n          for (let k = 0; k < 256; k++) {\n            let u = Math.pow(k / 255, effG);\n            u = u + 0.38 * u * (1 - u) * (u - 0.42);\n            if (u > 0.82) {\n              const t = (u - 0.82) / (1.0 - 0.82);\n              u = 0.82 + (1.0 - 0.82) * (3 * t * t - 2 * t * t * t);\n              if (u >= 0.96) u = 1.0;\n            }\n            let v = u * 255;\n            if (v < 0) v = 0; else if (v > 255) v = 255;\n            if (adjB) {\n      