  card.style.display = boothType === 'photo' ? '' : 'none';      // trading card / certificate booths have nothing to separate\n        var tg = document.getElementById('tierSplitToggle'); if (tg) tg.checked = !!tierSplit;\n        var on = tierSplitOn();\n        var colBtn = document.getElementById('tierCollapseBtn');\n        var tBody = document.getElementById('tierBody');\n        if (colBtn) colBtn.style.display = on ? '' : 'none';\n        if (tBody) tBody.style.display = on && (!colBtn || colBtn.getAttribute('aria-expanded') !== 'false') ? '' : 'none';\n        document.getElementById('tierOffHint').style.display = 'none';\n        document.getElementById('tierSteps').style.display = on ? '' : 'none';\n        var sizes = null; try { sizes = printSettings(); } catch (e) { }\n        var pc = document.getElementById('ppTierCard');\n        if (pc) pc.style.display = on && sizes ? '' : 'none';\n        if (!on) return;\n        var c = tierCounts();\n        var cnt = document.getElementById('tierCount');\n        if (cnt) cnt.textContent = 'You have ' + c.receipt + ' B&W, ' + c.photo + ' colour' + (c.all ? ' and ' + c.all + ' either-way' : '') + ' layout' + (c.receipt + c.photo + c.all === 1 ? '' : 's') + '. ' +\n          (c.receipt + c.all === 0 ? 'No B&W layout yet: the Receipt layouts are B&W, or set one of your frames to B&W.' : 'Tap a layout to see where it prints.');\n        var li2 = document.getElementById('tierStep2'); if (li2) li2.classList.toggle('done', c.receipt + c.all > 0 && c.photo + c.all > 0);\n        var rN = tierPrinters.receipt || '', pN = tierPrinters.photo || '';\n        var li3 = document.getElementById('tierStep3'); if (li3) li3.classList.toggle('done', !!(sizes && rN && pN));\n        var st = document.getElementById('tierPrinterState');\n        if (st) st.textContent = !sizes ? 'Printing is not turned on for this booth yet, so there is nothing to connect.'\n          : '🧾 B&W → ' + (rN || 'not chosen yet') + '   ·   🎨 Colour → 