 0.3 : 0.02;                       // text bubbles can be wider than their box\n        var key = tone + '|' + d.src + '|' + rs + '|' + (b.h / b.w).toFixed(3);\n        var hit = STK_TONE[key];\n        if (hit) return hit;\n        var c = document.createElement('canvas');\n        var cw = Math.ceil(b.w * k * (1 + 2 * pad)), ch = Math.ceil(b.h * k * (1 + 2 * pad));\n        c.width = Math.max(1, cw); c.height = Math.max(1, ch);\n        var x = c.getContext('2d');\n        x.translate(c.width / 2, c.height / 2);\n        if (isB) drawSticker(x, d.src.slice(2), b.w * k);\n        else x.drawImage(b.img, -b.w * k / 2, -b.h * k / 2, b.w * k, b.h * k);\n        x.setTransform(1, 0, 0, 1, 0, 0);\n        var im = x.getImageData(0, 0, c.width, c.height), p = im.data, n = c.width * c.height, i, fc = [0, 0, 0];\n        if (tone === 'grey' || dots) {\n          var g = new Float32Array(n);\n          // Darkened (gamma 2.2): a gold star or a pastel sticker is a light grey, which a thermal printer leaves almost blank.\n          // White stays white and black stays black, so the sticker keeps its shape and highlights.\n          for (i = 0; i < n; i++) g[i] = 255 * Math.pow((0.299 * p[i * 4] + 0.587 * p[i * 4 + 1] + 0.114 * p[i * 4 + 2]) / 255, 2.2);\n          if (dots) {                                                      // the same dots as the photos (Floyd-Steinberg)\n            var w = c.width;\n            for (i = 0; i < n; i++) {\n              if (p[i * 4 + 3] < 128) { p[i * 4 + 3] = 0; continue; }\n              var o = g[i], nv = o < 128 ? 0 : 255, e = o - nv, xx = i % w;\n              g[i] = nv; p[i * 4 + 3] = 255;\n              if (xx + 1 < w) g[i + 1] += e * 7 / 16;\n              if (i + w < n) { if (xx > 0) g[i + w - 1] += e * 3 / 16; g[i + w] += e * 5 / 16; if (xx + 1 < w) g[i + w + 1] += e / 16; }\n            }\n          }\n          for (i = 0; i < n; i++) p[i * 4] = p[i * 4 + 1] = p[i * 4 + 2] = g[i];\n        } else {\n          var fk = tone.sl